/**
 * A community member's links to their own profiles elsewhere, shown beside
 * their name in the member directory (601 [KB22], unit U12; added
 * 6 November 2026). Browser-safe: the member's page checks each box with
 * memberLinkFrom as it is typed, and the server keeps by the same rule.
 *
 * Only what lib/store-socials.ts already accepts for a store, and less:
 *
 *   - a page on one of the known social networks, at an https address on
 *     that network's own host, rebuilt by socialUrl; never the network's own
 *     front page, and on Substack only a publication's own address under
 *     substack.com; a handle alone is not enough, because nothing says which
 *     network it is on;
 *   - never an email address (other members never see a member's address),
 *     a phone number (WhatsApp) or a website of any kind, so the directory
 *     cannot send people anywhere but those networks' own sites; nor a
 *     network's own link redirector, nor an address that carries another
 *     address in its path or query;
 *   - without what a share button adds to the query or the fragment (who
 *     shared it, not where it goes), keeping a query that names the profile
 *     (Facebook's profile.php?id=);
 *   - at most MAX_MEMBER_LINKS, each at most MAX_MEMBER_LINK_URL characters,
 *     the same profile once however it was written.
 *
 * The member adds them on their own page and they show only while the member
 * chose to be listed, has a name, and is neither muted nor taken out
 * (shownLinks). They live in the member's own record (lib/community.ts), so
 * they are erased with it (lib/community-erasure.ts) and copied with it
 * (lib/person-copy.ts). The directory links them with no tracking and no
 * referrer (MEMBER_LINK_REL).
 */
import { SOCIALS, networkFor, parseSocials, socialShown, socialUrl, type Social, type SocialNetwork } from "@/lib/store-socials";

/** The networks a member may link to: the social ones, without email, a phone or a website. */
export const MEMBER_LINK_NETWORKS: readonly SocialNetwork[] = [
  "instagram",
  "tiktok",
  "youtube",
  "x",
  "facebook",
  "linkedin",
  "threads",
  "pinterest",
  "twitch",
  "spotify",
  "substack",
  "github",
  "discord",
  "telegram",
  "snapchat",
  "bluesky",
];

export const MAX_MEMBER_LINKS = 3;
export const MAX_MEMBER_LINK_URL = 200;

/**
 * How the directory links them: a member's words, not the store's (ugc), not
 * vouched for (nofollow), and opened without telling the other site which
 * community the reader came from (noreferrer). Not "me": the directory page
 * is a list of many people, so it is nobody's own page. Opened in the same
 * tab: a new window is a change the reader did not ask for.
 */
export const MEMBER_LINK_REL = "ugc nofollow noreferrer";

/**
 * What share buttons add to an address to say who shared it: Instagram's
 * igsh, Spotify's si, X's s and t, TikTok's _t and _r, Facebook's mibextid,
 * YouTube's feature, and the usual campaign and click marks.
 */
const SHARE_MARKS = /^(utm_.*|igsh|igshid|si|s|t|_t|_r|mibextid|fbclid|gclid|feature|ref|ref_src|ref_url|is_from_webapp|sender_device)$/i;

/**
 * A network's own link redirector: on the network's host, but it sends the
 * reader to another site under a label that says the network (Facebook's
 * l.php and its l./lm. hosts, Instagram's linkshim and l. host, YouTube's
 * redirect, LinkedIn's redir). Never anyone's profile.
 */
const REDIRECTOR_HOST = /^(l|lm)\.(facebook\.com|fb\.com|instagram\.com)$/;
const REDIRECTOR_PATH: Partial<Record<SocialNetwork, RegExp>> = {
  facebook: /^\/(l\.php|flx\/)/i,
  instagram: /^\/linkshim(\/|$)/i,
  youtube: /^\/redirect(\/|$)/i,
  linkedin: /^\/redir(\/|$)/i,
};

/** The text decoded as far as it goes (at most three times); an escape that does not decode leaves it as it is. */
function decoded(text: string): string {
  let out = text;
  for (let i = 0; i < 3; i += 1) {
    let next: string;
    try {
      next = decodeURIComponent(out);
    } catch {
      return out;
    }
    if (next === out) return out;
    out = next;
  }
  return out;
}

/**
 * Whether a piece of the address carries another address: a scheme's "://"
 * anywhere, a value starting "//", or a "//" still escaped after decoding
 * (written more times over, or beside an escape that does not decode), which
 * is refused rather than read as nothing.
 */
function carriesAddress(piece: string): boolean {
  const text = decoded(piece);
  return text.includes("://") || text.startsWith("//") || /%2f%2f/i.test(text);
}

function allowed(network: unknown): network is SocialNetwork {
  return typeof network === "string" && (MEMBER_LINK_NETWORKS as readonly string[]).includes(network);
}

/** The address cleaned of share marks and its fragment; "" when it is not one a member may link to on that network. */
function cleaned(network: SocialNetwork, href: string): string {
  let url: URL;
  try {
    url = new URL(href);
  } catch {
    return "";
  }
  if (url.protocol !== "https:") return "";
  for (const key of [...url.searchParams.keys()]) if (SHARE_MARKS.test(key)) url.searchParams.delete(key);
  url.hash = "";
  const host = url.hostname.toLowerCase();
  // A redirector, or anything that carries another address in its path or
  // what is left of its query, sends the reader off the network.
  if (REDIRECTOR_HOST.test(host) || REDIRECTOR_PATH[network]?.test(url.pathname)) return "";
  if (url.pathname.includes("//") || carriesAddress(url.pathname)) return "";
  for (const [key, value] of url.searchParams) if (carriesAddress(key) || carriesAddress(value)) return "";
  // Substack's address is the publication's own name under substack.com;
  // everywhere else the network's front page is nobody's profile.
  if (network === "substack" ? host === "substack.com" || host === "www.substack.com" : url.pathname === "/") return "";
  const out = url.href;
  return out.length > MAX_MEMBER_LINK_URL ? "" : out;
}

/** One link as typed: kept when it is a page on an allowed network's own site; null otherwise. */
export function memberLinkFrom(typed: unknown): Social | null {
  if (typeof typed !== "string") return null;
  const text = typed.trim();
  if (!text || text.length > 300) return null;
  // Any scheme but https (http, mailto, javascript) is refused; one with none is read as https.
  if (/^[a-z][a-z0-9+.-]*:/i.test(text) && !/^https:\/\//i.test(text)) return null;
  const full = /^https:\/\//i.test(text) ? text : `https://${text}`;
  const network = networkFor(full);
  if (!allowed(network)) return null;
  // socialUrl sees a full address, so it only ever checks the host; it never
  // turns a bare word into somebody's profile.
  const url = cleaned(network, socialUrl(network, full));
  return url ? { network, url } : null;
}

/** The same profile however it was written: no www, any case, no trailing slash. */
function sameKey(url: string): string {
  return url.toLowerCase().replace(/^https:\/\/www\./, "https://").replace(/\/(?=$|\?)/, "");
}

function addOnce(out: Social[], link: Social): void {
  if (!out.some((l) => sameKey(l.url) === sameKey(link.url))) out.push(link);
}

/** The links a member sent, in order: what is kept, and how many were turned away. */
export function memberLinksFromForm(typed: unknown[]): { links: Social[]; refused: number } {
  const links: Social[] = [];
  let refused = 0;
  typed.forEach((one, i) => {
    if (typeof one !== "string" || !one.trim()) return;
    // Boxes past the last one the page draws are never kept, and say so.
    const link = i < MAX_MEMBER_LINKS ? memberLinkFrom(one) : null;
    if (!link) refused += 1;
    else addOnce(links, link);
  });
  return { links, refused };
}

/**
 * The links as a member's record keeps them, read back: through the store's
 * own reading (parseSocials) and then this file's rule, so a record written
 * by hand or under an older rule never puts an address on the page that the
 * form would refuse today.
 */
export function parseMemberLinks(raw: unknown): Social[] {
  const out: Social[] = [];
  for (const social of parseSocials(Array.isArray(raw) ? raw.filter((e) => e && typeof e === "object" && allowed((e as Social).network)) : [])) {
    if (out.length >= MAX_MEMBER_LINKS) break;
    const link = memberLinkFrom(social.url);
    if (link && link.network === social.network) addOnce(out, link);
  }
  return out;
}

/** What the directory may show of a member's links (already read back by parseMemberLinks): none unless they are listed, named, not muted and not taken out. */
export function shownLinks(member: { dir: boolean; n: string; muted: boolean; removed: boolean; s?: Social[] }): Social[] {
  if (!member.dir || !member.n || member.muted || member.removed) return [];
  return member.s ?? [];
}

/**
 * The words each link shows: the network's own name, and where two of one
 * member's links are on the same network, the address too, so each says
 * where it goes on its own (WCAG 2.4.9).
 */
export function memberLinkLabels(links: Social[]): string[] {
  return links.map((link) => {
    const label = SOCIALS[link.network].label;
    const twice = links.filter((l) => l.network === link.network).length > 1;
    return twice ? `${label} (${socialShown(link.url)})` : label;
  });
}

lib/store-data.ts:
/**
 * A store's data room (lib/store-data-rules.ts says what it is and why):
 * the bytes it keeps in the database, counted where they are written.
 *
 *   nl:data:<store key>   hash: "#" -> bytes counted in all; "o" -> bytes its
 *                         orders left; <slot> -> bytes one record or one kind
 *                         of record is counted at
 *
 * A write names its slots and what each now weighs ("p:<product>" set to
 * 2,400) or how much it grew or shrank ("contacts" by +312). The script
 * below works out what that changes in all, and refuses a change that grows
 * the total past the room, before anything is written: the caller writes
 * only when it was taken. A change that shrinks or keeps the total is always
 * taken, so deleting never fails for want of room. An order's bytes are
 * added by the writes that leave them, at what each really adds
 * (lib/order-data.ts, slot "o"), never refused: their room is held up front
 * at the checkout (lib/order-admission.ts).
 *
 * What this errs toward. A record whose deletion is not given back stays
 * counted: the room looks fuller than it is, which costs the creator a
 * little room and never costs us storage nobody pays for. Unknown is
 * closed: when the room cannot be read or written, the write is refused
 * with a sentence saying to try again, the way a store figure is
 * (lib/store-allowance.ts).
 *
 * scripts/test_store_data_redis.py runs the script on a real Redis.
 */
import { isRedisConfigured, redisPipeline } from "@/lib/redis";
import { StoreFullError } from "@/lib/store-full";
import { largerPlanFor } from "@/lib/larger-plan";
import { type DataFields, contentRoomFor, dataFullWords, dataRoomFor } from "@/lib/store-data-rules";

/** What a store is kept under, and what its room is measured by. */
export type DataStore = DataFields & { sid?: string; statsId?: string | null; handle?: string };

/**
 * One slot's change: its new weight (`set`), or what it grew or shrank by.
 * `until` (milliseconds) counts it in the slot of the month that time falls
 * in instead, for a record that expires by itself: the whole month's slot
 * comes off the room once the month is over, without anything deleting it.
 */
export type DataChange = { slot: string; bytes: number; set?: boolean } | { until: number; bytes: number };

export type DataTaken = { ok: true; used: number } | { ok: false; reason: "full" | "unknown"; used: number; room: number; message: string };

/**
 * KEYS[1] the store's room. ARGV[1] how far a change may grow it, ARGV[2]
 * "1" to take the change whatever it comes to, ARGV[3] this month
 * ("2026-10", UTC), then (mode, slot, bytes) three at a time: mode "s" sets
 * the slot to bytes, "a" adds bytes to it (never below zero). A slot named
 * "~2027-11" holds what expires by itself in that month, listed in "~"; every
 * call first takes the months that are over off the total. The room's own
 * field for each slot is counted in the total as well (64 bytes). Answers
 * {1, total} when taken, {0, total} when it would pass the room (nothing
 * written but the months taken off), {-1, total} for what it cannot read.
 */
export const TAKE_DATA = `-- marktmorgen:store-data:v1
local limit = tonumber(ARGV[1])
local always = ARGV[2] == '1'
local month = ARGV[3] or ''
if not limit or limit < 0 or not string.match(month, '^%d%d%d%d%-%d%d$') or (#ARGV - 3) % 3 ~= 0 then return {-1, 0} end
local total = tonumber(redis.call('HGET', KEYS[1], '#') or '0')
if not total then return {-1, 0} end
for i = 4, #ARGV, 3 do
  local mode = ARGV[i]
  local slot = ARGV[i + 1]
  local n = tonumber(ARGV[i + 2])
  if not n or n ~= n or n == math.huge or n == -math.huge or slot == '#' or slot == '~' or slot == '' or (mode ~= 's' and mode ~= 'a') then return {-1, total} end
  if string.sub(slot, 1, 1) == '~' then
    local m = string.sub(slot, 2)
    if mode ~= 'a' or not string.match(m, '^%d%d%d%d%-%d%d$') or m < month then return {-1, total} end
  end
end
local months = {}
local listed = redis.call('HGET', KEYS[1], '~') or ''
local relist = false
for m in string.gmatch(listed, '[^,]+') do
  if m < month then
    local held = tonumber(redis.call('HGET', KEYS[1], '~' .. m) or '0') or 0
    -- Its bytes and its own field.
    if held > 0 then total = total - held - 64 end
    redis.call('HDEL', KEYS[1], '~' .. m)
    relist = true
  else
    months[m] = true
  end
end
if total < 0 then total = 0 end
local function keep()
  if relist then
    local list = {}
    for m in pairs(months) do list[#list + 1] = m end
    table.sort(list)
    if #list > 0 then redis.call('HSET', KEYS[1], '~', table.concat(list, ',')) else redis.call('HDEL', KEYS[1], '~') end
  end
  redis.call('HSET', KEYS[1], '#', total)
end
local now = {}
local order = {}
local delta = 0
for i = 4, #ARGV, 3 do
  local mode = ARGV[i]
  local slot = ARGV[i + 1]
  local n = tonumber(ARGV[i + 2])
  if string.sub(slot, 1, 1) == '~' then
    local m = string.sub(slot, 2)
    if not months[m] then
      months[m] = true
      relist = true
    end
  end
  local old = now[slot]
  if old == nil then
    old = tonumber(redis.call('HGET', KEYS[1], slot) or '0') or 0
    order[#order + 1] = slot
  end
  local new = old + n
  if mode == 's' then new = n end
  if new < 0 then new = 0 end
  new = math.floor(new)
  now[slot] = new
  delta = delta + (new - old)
  -- The room's own field for a slot is counted too: 64 bytes while it is there.
  if old == 0 and new > 0 then delta = delta + 64 elseif old > 0 and new == 0 then delta = delta - 64 end
end
if delta > 0 and not always and total + delta > limit then
  keep()
  return {0, total}
end
for _, slot in ipairs(order) do
  if now[slot] > 0 then
    redis.call('HSET', KEYS[1], slot, now[slot])
  else
    redis.call('HDEL', KEYS[1], slot)
  end
end
total = total + delta
if total < 0 then total = 0 end
keep()
return {1, total}`;

/** "2026-10": the UTC month a time falls in, what TAKE_DATA's month slots are named by. */
export function monthOf(ms: number): string {
  return new Date(ms).toISOString().slice(0, 7);
}

/**
 * The key a store's room is kept under: its id (or, for a store not yet
 * given one, its statistics id or address). Nothing here needs node:crypto,
 * so the files the studio's editors share with the server can count.
 */
export function dataKey(store: Pick<DataStore, "sid" | "statsId" | "handle">): string | null {
  const raw = (store.sid || store.statsId || store.handle || "").replace(/[^A-Za-z0-9_-]/g, "_").slice(0, 80);
  return raw ? `nl:data:${raw}` : null;
}

function argsOf(changes: DataChange[], nowMs: number): (string | number)[] | null {
  const out: (string | number)[] = [];
  for (const change of changes) {
    if (!Number.isFinite(change.bytes)) return null;
    if ("until" in change) {
      // Never a month already over: what expires sooner is counted in this one.
      if (!Number.isFinite(change.until)) return null;
      out.push("a", `~${monthOf(Math.max(change.until, nowMs))}`, Math.ceil(change.bytes));
      continue;
    }
    if (typeof change.slot !== "string" || !change.slot || change.slot === "#" || change.slot.startsWith("~") || change.slot.length > 200) return null;
    out.push(change.set ? "s" : "a", change.slot, Math.ceil(change.bytes));
  }
  return out;
}

/**
 * What a script that ran TAKE_DATA answered ({state, total}), read as run
 * reads it: for a write that takes its room in the same script as itself
 * (lib/creator-card.ts, lib/path.ts).
 */
export function dataTakenOf(store: DataStore, reply: unknown, nowSeconds = Date.now() / 1000): DataTaken {
  const room = dataRoomFor(store, nowSeconds);
  // Read exactly (Codex G2, #1961): {state, total}, the state the number 0 (full) or 1 (taken) and the total a safe
  // whole number of bytes, 0 or more. Anything else (missing, null, text, negative, an extra item) is not a receipt.
  const exact = Array.isArray(reply) && reply.length === 2 && (reply[0] === 0 || reply[0] === 1) && typeof reply[1] === "number" && Number.isSafeInteger(reply[1]) && reply[1] >= 0;
  if (!exact) return { ok: false, reason: "unknown", used: 0, room, message: "This can't be saved right now. Try again in a minute." };
  const used = reply[1] as number;
  if (reply[0] === 1) return { ok: true, used };
  return { ok: false, reason: "full", used, room, message: dataFullWords(used, room, largerPlanFor(store, nowSeconds)) };
}

async function run(store: DataStore, changes: DataChange[], always: boolean, nowSeconds: number): Promise<DataTaken> {
  const room = dataRoomFor(store, nowSeconds);
  const unknown = (used = 0): DataTaken => ({ ok: false, reason: "unknown", used, room, message: "This can't be saved right now. Try again in a minute." });
  if (changes.length === 0) return { ok: true, used: 0 };
  const key = dataKey(store);
  const args = argsOf(changes, nowSeconds * 1000);
  if (!key || !args || !isRedisConfigured()) return unknown();
  try {
    const [reply] = await redisPipeline([["EVAL", TAKE_DATA, 1, key, contentRoomFor(store, nowSeconds), always ? "1" : "0", monthOf(nowSeconds * 1000), ...args]]);
    return dataTakenOf(store, reply, nowSeconds);
  } catch (error) {
    console.error("could not count a store's data", error);
    return unknown();
  }
}

/**
 * Thrown by needData when a write does not fit. A StoreFullError, so every
 * studio route that already answers a full store answers this too
 * ("store_full"); the buyers' routes turn it into their own sentence.
 */
export class DataRoomError extends StoreFullError {
  constructor(readonly taken: Extract<DataTaken, { ok: false }>) {
    super(taken.message);
    this.name = "DataRoomError";
  }
}

/**
 * Takes room for a write before it is made, all or nothing. A change that
 * does not grow what the store keeps is always taken.
 */
export function takeData(store: DataStore, changes: DataChange[], now = Date.now()): Promise<DataTaken> {
  return run(store, changes, false, now / 1000);
}

/** The same, throwing DataRoomError when it is not taken, for a write that has nothing to say but no. */
export async function needData(store: DataStore, changes: DataChange[], now = Date.now()): Promise<void> {
  const taken = await takeData(store, changes, now);
  if (taken.ok) return;
  // Full is said as full; a room that could not be read is an ordinary failure, to try again.
  if (taken.reason === "full") throw new DataRoomError(taken);
  throw new Error("the store's data room could not be counted");
}

/** One slot grown (or shrunk) by `bytes`, before it is written; throws DataRoomError when it is not taken. */
export function needDataBytes(store: DataStore, slot: string, bytes: number, now = Date.now()): Promise<void> {
  return needData(store, [{ slot, bytes }], now);
}

/** One slot grown by `bytes`, before it is written. */
export function takeDataBytes(store: DataStore, slot: string, bytes: number, now = Date.now()): Promise<DataTaken> {
  return takeData(store, [{ slot, bytes }], now);
}

/**
 * Room for a record that expires by itself `seconds` from now, taken before
 * it is written: true when it fits. For what is worth keeping only while
 * there is room (a cache, a mark that saves work): the caller writes nothing
 * when this answers false, and goes on without it.
 */
export async function keepFor(store: DataStore, bytes: number, seconds: number, now = Date.now()): Promise<boolean> {
  if (!Number.isFinite(seconds) || seconds < 0) return false;
  return (await takeData(store, [{ until: now + seconds * 1000, bytes }], now)).ok;
}

/**
 * Gives back what a deletion freed, or puts right what a write that was
 * taken and then failed took. Never refuses and never throws.
 */
export async function giveData(store: DataStore, changes: DataChange[], now = Date.now()): Promise<void> {
  // What expires by itself is never given back early: it comes off with its month.
  const shrinking = changes.flatMap((change) => ("until" in change ? [] : [change.set ? change : { ...change, bytes: -Math.abs(change.bytes) }]));
  await run(store, shrinking, true, now / 1000).catch(() => undefined);
}

/**
 * Counts what is already written, as it is, whatever it comes to: a record
 * moved, or kept before the room was counted. Never refuses and never throws.
 */
export async function noteData(store: DataStore, changes: DataChange[], now = Date.now()): Promise<void> {
  await run(store, changes, true, now / 1000).catch(() => undefined);
}

/** One slot shrunk by `bytes`. Never refuses and never throws. */
export function giveDataBytes(store: DataStore, slot: string, bytes: number, now = Date.now()): Promise<void> {
  return giveData(store, [{ slot, bytes }], now);
}

/** What a store keeps, in bytes, and the room it has, for the studio; null when it cannot be read. */
export async function dataUsed(store: DataStore, now = Date.now()): Promise<{ used: number; orders: number; room: number } | null> {
  const key = dataKey(store);
  if (!key || !isRedisConfigured()) return null;
  try {
    const replies = await redisPipeline([["HMGET", key, "#", "o"]]);
    if (replies.length !== 1) return null;
    const reply = replies[0];
    if (!Array.isArray(reply) || reply.length !== 2) return null;
    // HMGET returns a decimal string for a kept hash field and null for one
    // that is absent. Coercing another value would turn an unknown count into
    // zero (or a fraction) before callers set aside the work it pays for.
    const count = (value: unknown): number | null => {
      if (value === null) return 0;
      if (typeof value !== "string" || !/^(0|[1-9][0-9]*)$/.test(value)) return null;
      const parsed = Number(value);
      return Number.isSafeInteger(parsed) ? parsed : null;
    };
    const used = count(reply[0]);
    const orders = count(reply[1]);
    if (used === null || orders === null) return null;
    return { used, orders, room: dataRoomFor(store, now / 1000) };
  } catch {
    return null;
  }
}

lib/store-data-rules.ts:
/**
 * What a store may keep in the database, the rules (added 18 October 2026).
 *
 * Every record a store keeps in Redis is paid for every month it is kept, at
 * Upstash's storage rate, and many of them grow with a store's age: its
 * products and pages, its contacts, its community's posts, the records each
 * of its orders leaves. Until this day only some kinds had a count of their
 * own, so no plan's worst month could say what a store's records cost
 * (tests/plan-cost-registry.ts, the line database-storage).
 *
 * So each store has a data room: a number of bytes, by plan, that what it
 * keeps there may fill, measured where it is written (lib/store-data.ts) and
 * given back where it goes. Two kinds of writes take from it:
 *
 *   - What a store chooses to keep: the store's own record and its
 *     products, pages, posts, notes, contacts, forms and what buyers write
 *     inside what they bought. Taken before it is written, all or nothing:
 *     what does not fit is refused with a sentence saying so, and nothing is
 *     written. Deleting, shortening and hiding are never refused.
 *   - What an order leaves: each of its records charged at what it really
 *     adds as it is written (lib/order-data.ts, since 18 October 2026; until
 *     then a fixed ORDER_DATA_BYTES an order), and never refused, because a
 *     buyer who paid must get everything. Its room is held up front instead,
 *     at the most an order can take: a new checkout is admitted only while
 *     the room has space for it and for every checkout still open
 *     (lib/order-admission.ts), the way the month's order figure is, and
 *     what a store chooses to keep may fill the room only up to
 *     ORDER_RESERVE_WINDOWS windows of orders from the top, so a full room
 *     never stops sales on its own.
 *
 * Records that are not in the room are bounded another way, each in
 * tests/store-data-registry.ts: they expire within days of the use that
 * wrote them, or are capped in number and size, or belong to the company
 * and not to a store. That file fails when a key family is added without
 * saying which.
 *
 * Pure and browser-safe: the studio shows the same figures the writes are
 * refused at.
 */
import type { Tier } from "@/lib/plan";
import { paidOrdersLimitFor } from "@/lib/order-rules";
import { MAX_CART } from "@/lib/cart-rules";
import { MAX_BUMPS } from "@/lib/product-extras";
import { MAX_BUNDLE_ITEMS } from "@/lib/bundle-rules";
import { type PlanFields, type Standing, standingOf } from "@/lib/plan-standing";

const MB = 1_000_000;

/**
 * The room each plan's store has in the database, in bytes: what it keeps
 * and what its orders leave, together. Sized so each plan keeps the owner's
 * 60% after tax at full use of everything (tests/spend-floor.test.ts).
 */
export const DATA_ROOM_BYTES: Record<Tier, number> = {
  creator: 18 * MB,
  pro: 135 * MB,
  scale: 250 * MB,
};

/**
 * The room of a store that pays nothing: a free trial, no plan, a plan that
 * ended. What it already keeps stays; past this nothing new is kept.
 */
export const NON_PAYING_DATA_ROOM_BYTES: Record<Exclude<Standing, "paid">, number> = {
  trial: 10 * MB,
  none: 5 * MB,
  ended: 5 * MB,
};

/**
 * The most one order can keep for good, in bytes, whatever it holds: what a
 * checkout holds in the room while it is open (lib/order-admission.ts), and
 * the reserve for orders is counted in. What an order really keeps is
 * charged as it is written (lib/order-data.ts), and is far less. This is at
 * least everything an order can write that is kept for as long as the store
 * is (its buyer's contact and access, the community, the license key, the
 * podcast and Discord access a product gives, the sale an affiliate earns
 * on, its review's marks...), each at the most it can weigh, and
 * ITEM_DATA_BYTES more for each product it hands over
 * (tests/store-data-registry.ts adds them up and holds these above the sums).
 * What an order keeps only for a while is priced on its own, at every order
 * of the window (the registry's parts by the order).
 */
export const ORDER_DATA_BYTES = 4_608;

/**
 * What each product an order hands over keeps for good besides: its place in
 * the buyer's record of what they bought (lib/learn.ts, recordEnrollment).
 * A course's student row is written when they first open it, and takes its
 * own room then (touchStudent).
 */
export const ITEM_DATA_BYTES = 4_352;

/** The most products one order can hand over: a cart of MAX_CART, each with MAX_BUMPS added, every one a bundle of MAX_BUNDLE_ITEMS. */
export const MAX_ORDER_ITEMS = (MAX_CART + MAX_BUMPS) * MAX_BUNDLE_ITEMS;

/** The products a checkout of these hands over at the most: a bundle's each, every other one itself. */
export function itemsHandedOver(products: { bundle?: readonly string[] | null }[]): number {
  return Math.max(1, products.reduce((n, product) => n + (Array.isArray(product.bundle) && product.bundle.length > 0 ? product.bundle.length : 1), 0));
}

/** What an order of this many products takes from the room; a checkout holds it while it is open (lib/order-admission.ts). */
export function orderDataBytes(items: number): number {
  const n = Number.isSafeInteger(items) && items > 0 ? Math.min(items, MAX_ORDER_ITEMS) : 1;
  return ORDER_DATA_BYTES + n * ITEM_DATA_BYTES;
}

/**
 * What the records kept beside a product weigh at the most, in bytes,
 * counted in the room with the product from the day it is made: its stock
 * and copies sold, when its buyers were last written to and the latest send,
 * the prices made for a tier or yearly switch (four each), its team event
 * type and round-robin counts, the Discord roles it gives, its introductory
 * coupon, its waitlist and pre-order flags, its reviews' summary and the
 * email platform's tags for it, each at its largest with its key. Once the
 * product is deleted they stay counted for as long as the store is
 * (lib/store.ts): some are kept until they expire, some are never let go.
 */
export const PRODUCT_SIDE_BYTES = 8_192;

/**
 * How long a booked call's line in the store's diary is kept after the call
 * ended (18 October 2026). The diary is what makes a time unavailable; a call
 * long over makes nothing unavailable, and Stripe keeps the booking itself
 * (its checkout, with the time in its details), which is what every page and
 * refund reads. So the line is let go, and the room it took given back, on
 * the first look at the diary this many days after the call (lib/calls.ts).
 */
export const PAST_CALL_DAYS = 90;

/** Windows of a plan's orders, of one product each, that what a store keeps leaves room for. */
export const ORDER_RESERVE_WINDOWS = 2;

/**
 * What each entry a write adds is counted at besides its own bytes: the key
 * or field it is kept under, and what Redis keeps beside it. A review
 * ceiling, rounded up: keys here are under 120 characters.
 */
export const ENTRY_BYTES = 128;

/** Writes are counted in steps of this many bytes, rounded up. */
export const DATA_STEP_BYTES = 16;

export type DataFields = PlanFields & { tier?: Tier };

/** The room of this store, in bytes. */
export function dataRoomFor(store: DataFields, nowSeconds = Date.now() / 1000): number {
  const standing = standingOf(store, nowSeconds);
  if (standing === "paid") return DATA_ROOM_BYTES[store.tier ?? "creator"] ?? DATA_ROOM_BYTES.creator;
  return NON_PAYING_DATA_ROOM_BYTES[standing];
}

/** What is kept back from the room for orders, in bytes: ORDER_RESERVE_WINDOWS windows of the store's order figure. */
export function orderReserveFor(store: DataFields, nowSeconds = Date.now() / 1000): number {
  const orders = paidOrdersLimitFor(store, nowSeconds) ?? 0;
  return Math.min(dataRoomFor(store, nowSeconds), ORDER_RESERVE_WINDOWS * orders * orderDataBytes(1));
}

/** How far what a store chooses to keep may fill its room, in bytes. */
export function contentRoomFor(store: DataFields, nowSeconds = Date.now() / 1000): number {
  return Math.max(0, dataRoomFor(store, nowSeconds) - orderReserveFor(store, nowSeconds));
}

/**
 * What a record counts for, in bytes: the UTF-8 length of what is written,
 * and ENTRY_BYTES for each key, field or member it is kept under, rounded up
 * to DATA_STEP_BYTES. Strings and numbers are measured as written.
 */
export function dataBytes(values: (string | number | null | undefined)[] | string, entries = 1): number {
  const list = typeof values === "string" ? [values] : values;
  let bytes = Math.max(0, Math.floor(entries)) * ENTRY_BYTES;
  for (const value of list) {
    if (value === null || value === undefined) continue;
    const text = typeof value === "string" ? value : String(value);
    bytes += utf8Length(text);
  }
  return Math.ceil(bytes / DATA_STEP_BYTES) * DATA_STEP_BYTES;
}

/**
 * dataBytes for values known only by their total UTF-8 length, as a Redis script reports one (string.len counts
 * bytes): dataBytesOfLength(utf8Length(a) + utf8Length(b), n) === dataBytes([a, b], n).
 */
export function dataBytesOfLength(utf8Bytes: number, entries = 1): number {
  const bytes = Math.max(0, Math.floor(entries)) * ENTRY_BYTES + Math.max(0, Math.floor(utf8Bytes));
  return Math.ceil(bytes / DATA_STEP_BYTES) * DATA_STEP_BYTES;
}

/** UTF-8 bytes of a string, without a TextEncoder (so it runs anywhere). */
export function utf8Length(text: string): number {
  let n = 0;
  for (let i = 0; i < text.length; i += 1) {
    const code = text.charCodeAt(i);
    if (code < 0x80) n += 1;
    else if (code < 0x800) n += 2;
    else if (code >= 0xd800 && code <= 0xdbff) {
      n += 4;
      i += 1;
    } else n += 3;
  }
  return n;
}

/** "12.4 MB", "640 KB": bytes, the way the studio says them. */
export function dataWords(bytes: number): string {
  const b = Number.isFinite(bytes) && bytes > 0 ? bytes : 0;
  if (b >= MB) return `${(Math.round((b / MB) * 10) / 10).toLocaleString("en-US")} MB`;
  return `${Math.max(b > 0 ? 1 : 0, Math.round(b / 1000)).toLocaleString("en-US")} KB`;
}

/** The rooms in one sentence, for the pricing page, the help center and the terms. */
export function dataRoomListWords(names: Record<Tier, string>): string {
  return `${dataWords(DATA_ROOM_BYTES.creator)} on ${names.creator}, ${dataWords(DATA_ROOM_BYTES.pro)} on ${names.pro} and ${dataWords(DATA_ROOM_BYTES.scale)} on ${names.scale}`;
}

/** What the creator is told when something does not fit; `larger` whether this store can move to a larger plan now (lib/larger-plan.ts). */
export function dataFullWords(used: number, room: number, larger = false): string {
  return `Your store's data room is full (${dataWords(used)} of ${dataWords(room)}). Delete something you no longer need, such as old posts, drafts, pages or contacts${larger ? ", or move to a larger plan" : ""}.`;
}

/** What a buyer or visitor is told when what they wrote does not fit: it is the store's room, not theirs. */
export const DATA_FULL_BUYER_WORDS = "This store has no room for that right now, so it was not saved. Try again later.";

tests/community-member-links.test.ts:
/**
 * Links to a member's profiles elsewhere in the community's member directory
 * (601 [KB22], unit U12; added 6 November 2026; lib/member-links.ts).
 * Checked:
 *
 *   - only an https profile on a known social network's own host is kept,
 *     rebuilt by lib/store-socials.ts, without the query a share button adds;
 *     never an email address, a phone number, a website, a bare handle, an
 *     http address or a lookalike host; at most three, no repeats, and every
 *     box turned away is counted so the member is told;
 *   - a record read back is cleaned the same way, so nothing the form would
 *     refuse today reaches the page;
 *   - links show only for a member who is listed, named, not muted and not
 *     taken out;
 *   - the member record (and so the walk that reads it) stays inside its
 *     stated worst size with the links in it;
 *   - the directory draws each link with a name that says whose profile and
 *     where (WCAG 2.4.9) and contains the visible word (2.5.3), no new window,
 *     no referrer; the member's page asks for them in labeled boxes; the
 *     route keeps them only from that page and says when one was turned away;
 *   - the record that holds them is erased and copied with the person, and
 *     the privacy page and the help say what is kept and who sees it.
 */
import { readFileSync } from "node:fs";
import {
  MAX_MEMBER_LINKS,
  MAX_MEMBER_LINK_URL,
  MEMBER_LINK_NETWORKS,
  MEMBER_LINK_REL,
  memberLinkFrom,
  memberLinkLabels,
  memberLinksFromForm,
  parseMemberLinks,
  shownLinks,
} from "@/lib/member-links";
import { readMember } from "@/lib/community";
import { MEMBER_ROW_BYTES } from "@/lib/api-read-rules";
import { networkFor } from "@/lib/store-socials";
import { WALK_MEMBER_BYTES } from "@/lib/community-walk";
import { MAX_ANSWER, MAX_DISPLAY_NAME, MAX_QUESTION, MAX_QUESTIONS } from "@/lib/community-text";
import { COMMUNITY_WORDS } from "@/lib/buyer-words/community";
import { communityNotices } from "@/components/community-parts";
import { PERSON_DATA } from "@/lib/person-data";
import { store as redis } from "./redis-stub";
import { done, is, part } from "./check";

const url = (typed: string) => memberLinkFrom(typed)?.url ?? null;

part("What a member may link to");
is("an Instagram profile is kept as its own address", memberLinkFrom("https://www.instagram.com/ana.silva"), { network: "instagram", url: "https://www.instagram.com/ana.silva" });
is("an address typed without https is read as https", url("instagram.com/ana"), "https://instagram.com/ana");
// Changed at review (rule 23): only what a share button adds is dropped, not the whole query, since
// some profiles are named by it (Facebook's profile.php?id=).
is("what a share button adds after ? or # is dropped", [url("https://www.instagram.com/ana?igsh=abc123&utm_source=qr#top"), url("https://open.spotify.com/user/ana?si=abc"), url("https://x.com/ana?s=20&t=abc")], ["https://www.instagram.com/ana", "https://open.spotify.com/user/ana", "https://x.com/ana"]);
is("a profile named by its query keeps it", url("https://www.facebook.com/profile.php?id=100012345&mibextid=abc"), "https://www.facebook.com/profile.php?id=100012345");
is("a handle with a dot after @ is a profile, not an email address", [url("https://www.tiktok.com/@ana.silva"), url("https://www.youtube.com/@ana.silva"), url("https://www.threads.net/@ana.silva")], ["https://www.tiktok.com/@ana.silva", "https://www.youtube.com/@ana.silva", "https://www.threads.net/@ana.silva"]);
is("the network itself is no one's profile", [url("https://instagram.com"), url("https://www.instagram.com/"), url("https://substack.com/"), url("https://www.substack.com/ana")], [null, null, null, null]);
is("a Substack is its own address under substack.com", url("https://ana.substack.com"), "https://ana.substack.com/");
is("YouTube, TikTok, LinkedIn and GitHub profiles are kept", ["https://www.youtube.com/@ana", "https://www.tiktok.com/@ana", "https://www.linkedin.com/in/ana", "https://github.com/ana"].map((t) => memberLinkFrom(t)?.network), ["youtube", "tiktok", "linkedin", "github"]);
is("a handle alone names no network, so it is not kept", [url("@ana"), url("ana")], [null, null]);
is("an email address is never a member's link", [url("ana@example.com"), url("mailto:ana@example.com")], [null, null]);
is("a phone number (WhatsApp) is never a member's link", [url("https://wa.me/15550100000"), url("+" + "1 (555) 010-0000")], [null, null]);
is("a website that is no social network is not kept", url("https://example.com/me"), null);
is("http is not kept", url("http://www.instagram.com/ana"), null);
is("a host that only looks like the network is not kept", [url("https://instagram.com.evil.example/ana"), url("https://evilinstagram.com/ana"), url("https://evil.example/instagram.com/ana")], [null, null, null]);
// Added at review (LEVE, independent review of 6 November 2026, comment 6698301155): a network's own
// link redirector is on the network's host but sends the reader to another site, under a label
// that says the network (WCAG 2.4.9), so it is no profile.
const away = encodeURIComponent("https://evil.example/");
is("a network's own redirector to another site is not kept", [
  url(`https://l.facebook.com/l.php?u=${away}`),
  url(`https://lm.facebook.com/l.php?u=${away}`),
  url(`https://www.youtube.com/redirect?q=${away}`),
  url(`https://www.linkedin.com/redir/redirect?url=${away}`),
  url(`https://www.instagram.com/linkshim/?u=${away}`),
], [null, null, null, null, null]);
is("a query that carries another address is not kept, however it is written", [
  url(`https://www.pinterest.com/offsite/?url=${away}`),
  url("https://t.me/iv?url=//evil.example/"),
  url(`https://www.facebook.com/ana?next=${encodeURIComponent(away)}`),
  url("https://x.com/ana?u=https://evil.example/"),
], [null, null, null, null]);
is("an address inside the path is not kept", [url("https://x.com/https://evil.example/"), url(`https://x.com/go/${away}`)], [null, null]);
is("a redirector path or host is not kept even without a destination", [
  url("https://www.facebook.com/l.php?u=evil.example"),
  url("https://l.instagram.com/ana"),
  url("https://www.youtube.com/redirect?q=evil.example"),
], [null, null, null]);
is("a stored redirector is left out when read back", parseMemberLinks([{ network: "facebook", url: `https://l.facebook.com/l.php?u=${away}` }, { network: "youtube", url: `https://www.youtube.com/redirect?q=${away}` }]), []);
is("a profile's own query and path still pass", [url("https://www.facebook.com/profile.php?id=100012345"), url("https://www.youtube.com/@ana/videos"), url("https://www.linkedin.com/in/ana")], ["https://www.facebook.com/profile.php?id=100012345", "https://www.youtube.com/@ana/videos", "https://www.linkedin.com/in/ana"]);
is("an address with a user and password is not kept", url("https://user:pw@www.instagram.com/ana"), null);
is("a script address is not kept", url("javascript:alert(1)//instagram.com/"), null);
is("an address longer than the limit is not kept", url(`https://www.instagram.com/${"a".repeat(MAX_MEMBER_LINK_URL)}`), null);
is("email, WhatsApp and website are not among the networks", ["email", "whatsapp", "website"].some((n) => (MEMBER_LINK_NETWORKS as readonly string[]).includes(n)), false);

part("The network is read from the host, before anything looks like an email address");
is("store socials: a dotted handle after @ in an address is the network's", [networkFor("https://www.tiktok.com/@ana.silva"), networkFor("tiktok.com/@ana.silva")], ["tiktok", "tiktok"]);
is("store socials: an address alone is still email", [networkFor("ana.silva@example.com"), networkFor("mailto:ana@example.com")], ["email", "email"]);

part("Each link's words tell it apart");
is("one link on a network is named by the network", memberLinkLabels([{ network: "instagram", url: "https://www.instagram.com/ana" }]), ["Instagram"]);
is("two on the same network each say which", memberLinkLabels([{ network: "instagram", url: "https://www.instagram.com/ana" }, { network: "github", url: "https://github.com/ana" }, { network: "instagram", url: "https://www.instagram.com/ana.art" }]), ["Instagram (instagram.com/ana)", "GitHub", "Instagram (instagram.com/ana.art)"]);

part("What the form keeps");
const sent = memberLinksFromForm(["https://www.instagram.com/ana", "", "instagram.com/ana?igsh=x", "https://example.com"]);
// Changed at review (rule 23): the same profile written two ways (with or without www, a capital, a
// trailing slash, a share query) is one link, not two that read the same.
is("kept in order, a repeat once however it is written, empty boxes ignored", sent.links.map((l) => l.url), ["https://www.instagram.com/ana"]);
is("the same profile with a capital and a slash is a repeat", memberLinksFromForm(["https://github.com/ana", "github.com/Ana/"]).links.length, 1);
is("a box turned away is counted", memberLinksFromForm(["https://www.instagram.com/ana", "https://example.com"]).refused, 1);
is("a repeat is not a refusal", memberLinksFromForm(["https://github.com/ana", "https://github.com/ana"]), { links: [{ network: "github", url: "https://github.com/ana" }], refused: 0 });
const many = memberLinksFromForm(["https://github.com/a", "https://github.com/b", "https://github.com/c", "https://github.com/d"]);
is("at most three are kept, and a fourth is counted as turned away", [many.links.length, many.refused], [MAX_MEMBER_LINKS, 1]);
is("anything that is not text is ignored", memberLinksFromForm([null, 5, {}] as unknown[]), { links: [], refused: 0 });

part("What a record gives back");
is("a stored entry the form would refuse today is left out", parseMemberLinks([
  { network: "website", url: "https://example.com" },
  { network: "email", url: "mailto:a@example.com" },
  { network: "instagram", url: "https://evil.example/x" },
  { network: "instagram", url: "javascript:alert(1)" },
  { network: "x", url: "https://x.com/ana?ref=1" },
  { network: "x", url: "https://x.com/ana" },
  "https://x.com/bob",
]), [{ network: "x", url: "https://x.com/ana" }]);
is("never more than three", parseMemberLinks(["a", "b", "c", "d"].map((h) => ({ network: "github", url: `https://github.com/${h}` }))).length, MAX_MEMBER_LINKS);
is("anything that is not a list gives none", [parseMemberLinks(null), parseMemberLinks("x"), parseMemberLinks({})], [[], [], []]);

part("Who is shown with links");
const links = [{ network: "github" as const, url: "https://github.com/ana" }];
const base = { dir: true, n: "Ana", muted: false, removed: false, s: links };
is("a listed, named member shows them", shownLinks(base), links);
is("not listed shows none", shownLinks({ ...base, dir: false }), []);
is("no name shows none", shownLinks({ ...base, n: "" }), []);
is("a muted member shows none, so the creator's mute stops a spammer's links at once", shownLinks({ ...base, muted: true }), []);
is("a member taken out shows none", shownLinks({ ...base, removed: true }), []);

async function main(): Promise<void> {
part("The member record keeps them, cleaned, and stays inside its size");
const cid = "cmlinks01";
// Rule 23, main integration: exact member reads require explicit mute/removal booleans.
// These healthy fixtures retain the same link assertions; unknown records remain refused.
await redis.pipeline([
  ["HSET", `nl:cm:${cid}:m`, "kold", JSON.stringify({ k: "kold", e: "old@example.com", n: "Old", dir: true, muted: false, removed: false })],
  ["HSET", `nl:cm:${cid}:m`, "knew", JSON.stringify({ k: "knew", e: "new@example.com", n: "New", dir: true, muted: false, removed: false, s: [{ network: "github", url: new URL("/new", "https://github.com").href }, { network: "website", url: new URL("https://example.com").href }] })],
]);
is("a record from before links has none", (await readMember(cid, "kold"))?.s, []);
is("a record's links are read back cleaned", (await readMember(cid, "knew"))?.s, [{ network: "github", url: "https://github.com/new" }]);
// Changed at review (rule 23): a three-byte character, the most a cleaned unit weighs, not an emoji
// (two bytes a unit) or a quote (two), so an undercount would show.
const wide = "\u20ac";
const worst = {
  k: "k".repeat(64),
  // An address is not cleaned of control characters, so each can be a six-byte escape.
  e: `${"\u0001".repeat(64)}@${"d".repeat(185)}.com`,
  n: wide.repeat(MAX_DISPLAY_NAME),
  h: wide.repeat(MAX_DISPLAY_NAME),
  dir: true,
  mail: true,
  at: 9_999_999_999,
  seen: 9_999_999_999,
  muted: false,
  removed: false,
  t: "f".repeat(40),
  q: Array.from({ length: MAX_QUESTIONS }, () => wide.repeat(MAX_ANSWER)),
  qq: Array.from({ length: MAX_QUESTIONS }, () => wide.repeat(MAX_QUESTION)),
  qa: 9_999_999_999,
  s: Array.from({ length: MAX_MEMBER_LINKS }, (_, i) => ({ network: "substack", url: `https://${String(i).padEnd(MAX_MEMBER_LINK_URL - 22, "a")}.substack.com/` })),
};
// Changed at review (rule 23): one figure for a member record at its largest, the one the API's
// reads already use (lib/api-read-rules.ts), rather than a second one beside it.
is("a record with every field at its worst fits the one stated size", Buffer.byteLength(JSON.stringify(worst)) <= MEMBER_ROW_BYTES, true);
is("the walk that reads members is charged at that size", WALK_MEMBER_BYTES, MEMBER_ROW_BYTES);
is("the stated size names the links", readFileSync("lib/api-read-rules.ts", "utf8").includes("MAX_MEMBER_LINKS (3) links"), true);
}

part("Words, in every language of a store");
for (const [code, w] of Object.entries(COMMUNITY_WORDS)) {
  const named = w.linkOn("Ana", "Instagram");
  is(`${code}: each link says whose profile and on which network, and holds the visible word`, named.includes("Ana") && named.includes("Instagram"), true);
  is(`${code}: the boxes have a legend, a note, and a label each`, [w.linksLegend, w.linksNote, w.linkLabel(1), w.linkLabel(3)].every((t) => typeof t === "string" && t.length > 3) && w.linkLabel(1) !== w.linkLabel(3), true);
  is(`${code}: a turned-away link is told, as a warning`, communityNotices(code).savedlinkoff?.tone, "warn");
  // Changed at fix (rule 23): rather than finding the address in the words, the example they give is
  // read out and must be an Instagram profile the rule itself keeps.
  const example = typeof w.linkRefused === "string" ? /https:\/\/\S+?(?=\.?(?:\s|$))/.exec(w.linkRefused)?.[0] : undefined;
  is(`${code}: a box the rule would refuse says so beside it, before sending, with an example the rule keeps`, example !== undefined && memberLinkFrom(example)?.network === "instagram", true);
}
is("the note says links show only while listed", COMMUNITY_WORDS.en.linksNote.includes("only while you are listed"), true);

part("The pages and the route");
const members = readFileSync("app/[handle]/community/members/page.tsx", "utf8");
is("the directory draws only shownLinks(m)", members.includes("shownLinks(m)"), true);
is("each link has no referrer and is the member's own words", members.includes("rel={MEMBER_LINK_REL}") && MEMBER_LINK_REL === "ugc nofollow noreferrer", true);
// Changed at review (rule 23): named from memberLinkLabels, which tells two links on one network apart.
is("each link is named by whose profile and where", members.includes("aria-label={w.linkOn(m.n, labels[i])}") && members.includes("memberLinkLabels(links)"), true);
is("no link opens a new window", /target=/.test(members), false);
is("the links are a list with its own name", members.includes("<ul") && members.includes("aria-label={w.linksOf(m.n)}"), true);
// Changed at review (rule 23): the boxes moved into components/member-link-boxes.tsx, which checks each
// one with the server's own rule as it is typed, so a refused address stays in its box to fix (WCAG 3.3.7).
const you = readFileSync("app/[handle]/community/you/page.tsx", "utf8") + readFileSync("components/member-link-boxes.tsx", "utf8");
